import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"终端","description":"","frontmatter":{},"headers":[],"relativePath":"software/terminal.md","filePath":"software/terminal.md","lastUpdated":1791990988000}'),i={name:"software/terminal.md"};function p(l,a,o,c,h,d){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="终端" tabindex="-1">终端 <a class="header-anchor" href="#终端" aria-label="Permalink to &quot;终端&quot;">​</a></h1><h2 id="alacritty" tabindex="-1">Alacritty <a class="header-anchor" href="#alacritty" aria-label="Permalink to &quot;Alacritty&quot;">​</a></h2><p><a href="https://github.com/alacritty/alacritty" target="_blank" rel="noreferrer">https://github.com/alacritty/alacritty</a></p><p>GPU 加速的轻量终端，配置写在 <code>~/.config/alacritty/alacritty.toml</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S alacritty</span></span></code></pre></div><h2 id="kitty" tabindex="-1">Kitty <a class="header-anchor" href="#kitty" aria-label="Permalink to &quot;Kitty&quot;">​</a></h2><p><a href="https://github.com/kovidgoyal/kitty" target="_blank" rel="noreferrer">https://github.com/kovidgoyal/kitty</a></p><p>同样 GPU 加速，功能比 Alacritty 多一些（标签页、远程控制、 kitten 插件）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S kitty</span></span></code></pre></div><h2 id="wezterm" tabindex="-1">WezTerm <a class="header-anchor" href="#wezterm" aria-label="Permalink to &quot;WezTerm&quot;">​</a></h2><p><a href="https://github.com/wez/wezterm" target="_blank" rel="noreferrer">https://github.com/wez/wezterm</a></p><p>用 Lua 配置的 GPU 终端，自带分屏和串行端口支持，Windows / macOS 也能用</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S wezterm</span></span></code></pre></div><h2 id="tmux" tabindex="-1">tmux <a class="header-anchor" href="#tmux" aria-label="Permalink to &quot;tmux&quot;">​</a></h2><p><a href="https://github.com/tmux/tmux" target="_blank" rel="noreferrer">https://github.com/tmux/tmux</a></p><p>终端复用器，SSH 断开后会话不中断，配置文件 <code>~/.tmux.conf</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S tmux</span></span></code></pre></div><h2 id="nohup" tabindex="-1">nohup <a class="header-anchor" href="#nohup" aria-label="Permalink to &quot;nohup&quot;">​</a></h2><p>后台运行命令，关掉终端也不中断：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nohup command &amp;</span></span></code></pre></div><p>用 <code>jobs</code> 可以查看后台执行的任务。</p><h2 id="screen" tabindex="-1">screen <a class="header-anchor" href="#screen" aria-label="Permalink to &quot;screen&quot;">​</a></h2><p>启动新的 <code>screen</code> 会话：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>screen -S 会话名</span></span></code></pre></div><p>恢复会话（也可以用 ID）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>screen -r 会话名</span></span></code></pre></div><p>查看所有会话：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>screen -ls</span></span></code></pre></div><p>常用快捷键：</p><ul><li><code>Ctrl-a</code> + <code>d</code>：暂时分离当前会话，返回命令行</li><li><code>Ctrl-a</code> + <code>c</code>：创建一个新窗口</li><li><code>Ctrl-a</code> + <code>n</code>：切换到下一个窗口</li><li><code>Ctrl-a</code> + <code>p</code>：切换到前一个窗口</li><li><code>Ctrl-a</code> + <code>0..9</code>：切换到指定编号的窗口</li></ul><h2 id="zsh" tabindex="-1">Zsh <a class="header-anchor" href="#zsh" aria-label="Permalink to &quot;Zsh&quot;">​</a></h2><p><a href="https://www.zsh.org/" target="_blank" rel="noreferrer">https://www.zsh.org/</a></p><p>默认的 bash 之外的另一个 shell，插件生态丰富（oh-my-zsh）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S zsh</span></span></code></pre></div><p>设为默认 shell：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chsh -s /usr/bin/zsh</span></span></code></pre></div><h2 id="starship" tabindex="-1">Starship <a class="header-anchor" href="#starship" aria-label="Permalink to &quot;Starship&quot;">​</a></h2><p><a href="https://github.com/starship/starship" target="_blank" rel="noreferrer">https://github.com/starship/starship</a></p><p>终端提示符工具，显示 git 分支、语言版本等信息，需要配合 Nerd Fonts</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S starship</span></span></code></pre></div><h2 id="shell-补全-bash-completion" tabindex="-1">Shell 补全（bash-completion） <a class="header-anchor" href="#shell-补全-bash-completion" aria-label="Permalink to &quot;Shell 补全（bash-completion）&quot;">​</a></h2><p>安装 <code>bash-completion</code> 包即可，大部分场景会自动生效，无需手动配置。</p><p>安装后，多数包管理器会在 <code>/etc/profile.d/</code> 里创建自动加载脚本；若未自动生效，再手动编辑 <code>~/.bashrc</code> 并重载 <code>source ~/.bashrc</code>。</p><p>手动加载的写法（仅在自动加载失效时用）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># enable bash completion in interactive shells</span></span>
<span class="line"><span>if ! shopt -oq posix; then</span></span>
<span class="line"><span>  if [ -f /usr/share/bash-completion/bash_completion ]; then</span></span>
<span class="line"><span>    . /usr/share/bash-completion/bash_completion</span></span>
<span class="line"><span>  elif [ -f /etc/bash_completion ]; then</span></span>
<span class="line"><span>    . /etc/bash_completion</span></span>
<span class="line"><span>  fi</span></span>
<span class="line"><span>fi</span></span></code></pre></div><h2 id="历史记录" tabindex="-1">历史记录 <a class="header-anchor" href="#历史记录" aria-label="Permalink to &quot;历史记录&quot;">​</a></h2><p>清除当前 shell 会话的历史记录：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>history -c</span></span></code></pre></div><p>永久禁用历史记录，添加到 <code>~/.bashrc</code> 并 <code>source ~/.bashrc</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unset HISTFILE</span></span>
<span class="line"><span>HISTSIZE=0</span></span>
<span class="line"><span>HISTFILESIZE=0</span></span></code></pre></div>`,50)])])}const b=e(i,[["render",p]]);export{u as __pageData,b as default};
